const listArenaResultHistory = `-- name: ListArenaResultHistory :many
SELECT result_commit.id AS commit_id,
    result_commit.tournament_id,
    result_commit.roster_id,
    result_commit.series_id,
    result_commit.attempt_id,
    result_event.id AS result_event_id,
    result_event.server_sequence,
    result_event.result_state,
    result_event.result_reason,
    result_event.winner_id,
    game_revision.id AS game_revision_id,
    game_revision.revision_number AS game_revision_number,
    score_revision.id AS score_revision_id,
    score_revision.revision_number AS score_revision_number,
    score_revision.first_participant_wins,
    score_revision.second_participant_wins,
    result_commit.series_result_revision_id,
    result_commit.created_at
FROM arena_result_commits AS result_commit
INNER JOIN arena_result_events AS result_event
    ON result_event.id = result_commit.result_event_id
INNER JOIN arena_official_result_revisions AS game_revision
    ON game_revision.id = result_commit.game_result_revision_id
INNER JOIN arena_series_score_revisions AS score_revision
    ON score_revision.id = result_commit.series_score_revision_id
WHERE result_commit.tournament_id = $1
    AND result_commit.roster_id = $2
    AND result_commit.series_id = $3
    AND result_commit.attempt_id = $4
ORDER BY game_revision.revision_number
`

type ListArenaResultHistoryParams struct {
	TournamentID uuid.UUID
	RosterID     uuid.UUID
	SeriesID     uuid.UUID
	AttemptID    uuid.UUID
}

type ListArenaResultHistoryRow struct {
	CommitID               uuid.UUID
	TournamentID           uuid.UUID
	RosterID               uuid.UUID
	SeriesID               uuid.UUID
	AttemptID              uuid.UUID
	ResultEventID          uuid.UUID
	ServerSequence         int64
	ResultState            string
	ResultReason           string
	WinnerID               uuid.NullUUID
	GameRevisionID         uuid.UUID
	GameRevisionNumber     int64
	ScoreRevisionID        uuid.UUID
	ScoreRevisionNumber    int64
	FirstParticipantWins   int16
	SecondParticipantWins  int16
	SeriesResultRevisionID uuid.NullUUID
	CreatedAt              pgtype.Timestamptz
}

func (q *Queries) ListArenaResultHistory(ctx context.Context, arg ListArenaResultHistoryParams) ([]ListArenaResultHistoryRow, error) {
	rows, err := q.db.Query(ctx, listArenaResultHistory,
		arg.TournamentID,
		arg.RosterID,
		arg.SeriesID,
		arg.AttemptID,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListArenaResultHistoryRow{}
	for rows.Next() {
		var i ListArenaResultHistoryRow
		if err := rows.Scan(
			&i.CommitID,
			&i.TournamentID,
			&i.RosterID,
			&i.SeriesID,
			&i.AttemptID,
			&i.ResultEventID,
			&i.ServerSequence,
			&i.ResultState,
			&i.ResultReason,
			&i.WinnerID,
			&i.GameRevisionID,
			&i.GameRevisionNumber,
			&i.ScoreRevisionID,
			&i.ScoreRevisionNumber,
			&i.FirstParticipantWins,
			&i.SecondParticipantWins,
			&i.SeriesResultRevisionID,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

